window.futvizVista("origen-xg","<div class=\"rx-mount\" data-rx=\"origen_xg\" data-rx-id=\"origen-xg\" style=\"min-height:520px\"></div><script>(window.futvizVistas=window.futvizVistas||{})[\"origen-xg\"]={\"id\":\"origen-xg\",\"titulo\":\"De d\u00f3nde sale el xG\",\"bajada\":\"Cu\u00e1nto del xG de cada equipo sale de jugada abierta, de c\u00f3rner y de otros balones parados.\",\"pregunta\":\"\u00bfVive de los c\u00f3rners o construye jugando?\",\"tabla\":\"origen-xg\",\"queMirar\":\"Muestra c\u00f3mo genera peligro cada equipo, seg\u00fan de d\u00f3nde sale su xG. Cada barra reparte el xG seg\u00fan c\u00f3mo naci\u00f3 la ocasi\u00f3n: jugada abierta en gris y, en colores, c\u00f3rner, tiro libre directo y otro bal\u00f3n parado.\\nCon \u00ab% del xG\u00bb ves de qu\u00e9 v\u00eda depende cada equipo y con \u00abxG por partido\u00bb, cu\u00e1nto produce por ella. \u00abA favor\u00bb son los tiros que hace el equipo y \u00abEn contra\u00bb, los que recibe.\",\"fuente\":\"Understat\",\"segmentos\":[{\"id\":\"corner\",\"etiqueta\":\"C\u00f3rner\",\"balonParado\":true},{\"id\":\"libre\",\"etiqueta\":\"Tiro libre directo\",\"balonParado\":true},{\"id\":\"otro\",\"etiqueta\":\"Otro bal\u00f3n parado\",\"balonParado\":true},{\"id\":\"abierta\",\"etiqueta\":\"Jugada abierta\",\"balonParado\":false}],\"colores\":{\"claro\":{\"corner\":\"#d95f02\",\"libre\":\"#7570b3\",\"otro\":\"#1b9e77\"},\"oscuro\":{\"corner\":\"#f08a3c\",\"libre\":\"#a39fd6\",\"otro\":\"#3fc4a0\"}},\"ligasColores\":{\"claro\":{\"Bundesliga\":\"#e34948\",\"Serie A\":\"#2a78d6\",\"Ligue 1\":\"#2e413a\",\"La Liga\":\"#eda100\",\"Premier League\":\"#e87ba4\"},\"oscuro\":{\"Bundesliga\":\"#dd1d2d\",\"Serie A\":\"#2878d7\",\"Ligue 1\":\"#0c7b60\",\"La Liga\":\"#c28412\",\"Premier League\":\"#cc7193\"}}};</script>");